1	<!DOCTYPE html>
2	<html lang="{{language}}">
3	<head>
4	    <meta charset="UTF-8">
5	    <link rel="icon" type="image/x-icon" href="{{url_for(path='static/favicon.ico')}}">
6	    <meta name="viewport" content="width=device-width, initial-scale=1">
7	    <meta name="color-scheme" content="light dark" />
8	    <meta name="generator" content="Marmite" />
9	    {% block seo %}
10	    <meta property="og:title" content="{{ site.name }}">
11	    <meta property="og:description" content="{{ site.tagline }}">
12	    {% if site.card_image %}
13	    <meta property="og:image" content="{{url_for(path=site.card_image, abs=true)}}">
14	    {% endif %}
15	    {% if site.url %}
16	    <meta property="og:url" content="{{site.url}}">
17	    {% endif %}
18	    <meta property="og:type" content="website">
19	    <meta property="og:site_name" content="{{site.name}}">
20	    {% if site.extra.fediverse_verification %}
21	    <link rel="me" href="{{site.extra.fediverse_verification}}">
22	    {% endif %}
23	    {% endblock %}
24	    {%- block head %}
25	    <title>{% if title %}{{title}} | {%endif%}{{ site.name }}</title>
26	    <link rel="stylesheet" type="text/css" href="{{url_for(path='static/pico.min.css')}}">
27	    <link rel="stylesheet" type="text/css" href="{{url_for(path='static/marmite.css')}}">
28	    {% if site.extra.colorscheme %}
29	    <link rel="stylesheet" type="text/css" href="{{url_for(path='static/colorschemes/' ~ site.extra.colorscheme ~ '.css')}}">
30	    {% endif %}
31	    <link rel="stylesheet" type="text/css" href="{{url_for(path='static/custom.css')}}">
32	    {% endblock -%}
33	    {%- block feeds %}
34	    {%include 'base_feeds.html' ignore missing%}
35	    {% endblock %}
36	    {% if htmlhead is defined %}
37	    {{ htmlhead }}
38	    {% endif %}
39	</head>
40	<body>
41	    {% if announce is defined %}
42	    <div class="container-fluid announcement-wrapper">
43	        <div class="announcement">{{ announce }}</div>
44	    </div>
45	    {% endif %}
46	    <main class="container">
47	        {% if header is defined %}
48	           {{ header}}
49	        {% else %}
50	        <header class="header-content">
51	            <nav class="header-nav">
52	                <ul class="header-name">
53	                    <li>
54	                        <hgroup class="h-card">
55	                            <h2>
56	                                <a href="{{url_for(path='')}}" class="contrast p-name u-url">
57	                                    {% if site.logo_image %}
58	                                        <img src="{{url_for(path=site.logo_image)}}" alt="{{ site.name }}" class="u-photo">
59	                                    {% else %}
60	                                        {{ site.name }}
61	                                    {% endif %}
62	                                </a>
63	                            </h2>
64	                            {% if site.tagline %} <p class="p-note">{{ site.tagline }}</p> {% endif %}
65	                        </hgroup>
66	                    </li>
67	                </ul>
68	                <button id="menu-toggle" class="hamburger">&#9776;</button>
69	
70	                <ul class="header-menu" id="header-menu">
71	                    {% for item in menu %}
72	                      {% set name = item.0 %}
73	                      {% set url = item.1 %}
74	                    <li>
75	                        {% if current_page and current_page == url %}
76	                        <button class="menu-item active selected">{{name | safe }}</button>
77	                        {% else %}
78	                        <a class="menu-item secondary" {% if url is starting_with("http") %} href="{{url}}" target="_blank" {% else %} href="{{url_for(path=url)}}"{% endif %}>{{ name | safe }}</a>
79	                        {% endif %}
80	                    </li>
81	                    {% endfor %}
82	                    {% if site.extra.colormodetoggle %}
83	                        <li><span class="theme-toggle secondary" title="dark mode">&#9789;</span></li>
84	                    {% endif %}
85	                    {% if site.enable_search %}
86	                    <li><a href="#" id="search-toggle" class="secondary" title="Search (Ctrl + Shift + F)"> <span class="search-txt">Search</span><span class="search-magnifier"></span></a></li>
87	                    {% endif %}
88	                    <div class="underline"></div>
89	                </ul>
90	            </nav>
91	            {% if site.enable_search %}
92	            <div class="marmite-background-overlay" id="overlay-close"></div>
93	            <div class="marmite-search-bar hidden">
94	                <span>{{site.search_title}}</span>
95	                <button class="marmite-close-button" id="search-close">X</button>
96	                <input placeholder="Search" id="marmite-search-input" />
97	                <div class="marmite-search-bar-result">
98	                    <ul id="marmite-search-bar-result"></ul>
99	                </div>
100	            </div>
101	            {% endif %}
102	        </header>
103	        {% endif %}
104	        <section class="main-content">
105	            {% block main -%}{%- endblock %}
106	        </section>
107	        {% if footer is defined %}
108	           {{ footer}}
109	        {% else %}
110	        <footer class="footer-content grid">
111	            {{ site.footer | safe }}
112	            {% if site.extra.colorscheme_toggle %}
113	            <div class="colorscheme-toggle-div">
114	                colorscheme: <select name="colorscheme" class="colorscheme-toggle"><option value="default">default</option></select>
115	                <span class="theme-toggle secondary" title="dark mode">&#9789;</span>
116	            </div>
117	            {% endif %}
118	        </footer>
119	        {% endif %}
120	    </main>
121	    {%- block tail %}
122	    <script src="{{url_for(path='static/marmite.js')}}"></script>
123	    <script src="{{url_for(path='static/custom.js')}}"></script>
124	    {% if site.enable_search %}
125	    <script type="module" src="{{url_for(path='static/search.js')}}"></script>
126	    {% endif %}
127	    {% if site.extra.colorscheme_toggle %}    
128	    <script type="application/javascript" >
129	        colorschemeSwitcher();
130	    </script>
131	    {% endif %}
132	    {% if site.extra.colormode %}
133	        <script type="application/javascript">
134	            // If there is already a scheme saved in localstorage, load that, else load config
135	            if (themeSwitcher.scheme == "auto") {
136	                themeSwitcher.scheme = "{{ site.extra.colormode }}";
137	                themeSwitcher.updateIcon();
138	            }
139	        </script>
140	    {% endif %}
141	    {% endblock -%}
142	    {% if htmltail is defined %}
143	    {{ htmltail }}
144	    {% endif %}
145	</body>
146	</html>
